#!/usr/bin/env node
// Turkmen course (Daily Turkmen): tests for assets/js/turkmen-morph.js, the morphology engine (turkmen/TM-PROJECT.md
// section 3). Every expected form below was typed by hand from the written standard as TM-CURRICULUM.md records it
// (the answers to its open questions, with what each rests on), never generated by the engine, so a failure means
// the engine or this list is wrong. No dependencies; Node 18 or later.
//
//   node scripts/turkmen/morph-test.mjs            run everything; exit 1 on a failure
//   node scripts/turkmen/morph-test.mjs --verbose  also list the forms that pass
import path from "path";
import { createRequire } from "module";
import { fileURLToPath } from "url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const M = createRequire(import.meta.url)(path.join(ROOT, "assets/js/turkmen-morph.js"));
const VERBOSE = process.argv.includes("--verbose");
let forms = 0, other = 0;
const failures = [];

// check one form: kind "form" counts toward the known-correct forms, "check" is any other assertion
function check(label, fn, want, kind = "form") {
  let got;
  try { got = fn(); } catch (e) { got = `threw ${e.message}`; }
  const ok = Array.isArray(want) ? JSON.stringify(got) === JSON.stringify(want) : got === want;
  if (kind === "form") forms += Array.isArray(want) ? want.length : 1; else other++;
  if (!ok) failures.push(`${label}: expected ${JSON.stringify(want)}, got ${JSON.stringify(got)}`);
  else if (VERBOSE) console.log(`ok  ${label}: ${Array.isArray(want) ? want.join(", ") : want}`);
}
// a paradigm: six forms separated by |, men … olar; "-" skips a person; with has, the form only has to be a variant
function para(slug, base, list, has = false, o) {
  list.split("|").forEach((want, i) => {
    if (want === "-") return;
    check(`${slug} ${base} ${M.PERSONS[i]}${has ? " (variant)" : ""}`, () => {
      const r = M.form(slug, base, i, o);
      if (!r) return null;
      return has ? (r.variants.includes(want) ? want : r.variants.join(" / ")) : r.text;
    }, want);
  });
}
const dec = (base, o) => M.decline(base, o).text;
const build = (base, ids, o) => M.build(base, ids, o).text;
const third = (slug, base) => { const r = M.form(slug, base, "ol"); return r && r.text; };

// ─────────────────────────── 1. harmony and the rounding rule ───────────────────────────
for (const [v, a, y] of [["a", "a", "y"], ["o", "a", "y"], ["u", "a", "y"], ["y", "a", "y"], ["e", "e", "i"], ["ä", "e", "i"], ["i", "e", "i"],
  ["ö", "e", "i"], ["ü", "e", "i"]]) check(`harmony after ${v}`, () => M.harmonyA(v) + M.harmonyY(v), a + y, "check");
check("y is a vowel, ý a consonant", () => [M.isVowel("y"), M.isVowel("ý"), M.syllables("ýyl"), M.syllables("okuwçy")], [true, false, 1, 3], "check");
// a high suffix vowel in the second syllable after a rounded first syllable is u/ü, unless it ends the word
para("possessive", "öý", "öýüm|öýüň|öýi|öýümiz|öýüňiz|öýi");
para("possessive", "göz", "gözüm|gözüň|gözi|gözümiz|gözüňiz|gözi");
para("possessive", "dost", "dostum|dostuň|dosty|dostumyz|dostuňyz|dosty");
para("possessive", "gün", "günüm|günüň|güni|günümiz|günüňiz|güni");
para("possessive", "ýol", "ýolum|ýoluň|ýoly|ýolumyz|ýoluňyz|ýoly");
para("possessive", "ýurt", "ýurdum|ýurduň|ýurdy|ýurdumyz|ýurduňyz|ýurdy");
para("possessive", "okuwçy", "okuwçym|okuwçyň|okuwçysy|okuwçymyz|okuwçyňyz|okuwçysy");
para("possessive", "dogan", "doganym|doganyň|dogany|doganymyz|doganyňyz|dogany");
para("past", "bolmak", "boldum|bolduň|boldy|bolduk|bolduňyz|boldular");
para("past", "görmek", "gördüm|gördüň|gördi|gördük|gördüňiz|gördüler");
check("a stem's final y rounds once a suffix follows: gowurak, ulurak, gowumy, ulular, gowudy", () =>
  [build("gowy", ["RAK"]), build("uly", ["RAK"]), build("gowy", ["Q"]), dec("uly", { pl: true }), build("gowy", ["PCOP"])], ["gowurak", "ulurak", "gowumy", "ulular", "gowudy"]);
check("from the third syllable on: bolupdyr, oturyň, okuwçylar, öýümiz", () =>
  [third("perfect-ypdyr", "bolmak"), M.form("imperative", "oturmak", "siz").text, dec("okuwçy", { pl: true }), M.form("possessive", "öý", "biz").text],
  ["bolupdyr", "oturyň", "okuwçylar", "öýümiz"]);
check("stem vowels are spelt as they are: uzynlyk, otyryn", () => [build("uzyn", ["LYK"]), M.form("progressive-otyr", "okamak", "men").text],
  ["uzynlyk", "okap otyryn"]);
check("the particle's own vowel never rounds: ýokmydy, barmydy", () => [M.copula("ýok", { tense: "past", q: true, p: "ol" }).text,
  M.copula("bar", { tense: "past", q: true, p: "ol" }).text], ["ýokmydy", "barmydy"]);
check("boldumy, and boldymy as a variant (open question 1)", () => M.form("past-question", "bolmak", "ol").variants, ["boldumy", "boldymy"]);
check("stoluň, and stolyň as a variant for a one-syllable loanword (open question 1)", () => {
  const r = M.form("possessive", "stol", "sen"); return r.variants; }, ["stoluň", "stolyň"]);
check("dative and ablative never round: göze, gözden", () => [dec("göz", { case: "dat" }), dec("göz", { case: "abl" })], ["göze", "gözden"]);

// ─────────────────────────── 2. nouns: the five cases, voicing, vowel loss ───────────────────────────
// noun, accusative, dative, locative, ablative, genitive
for (const [w, acc, dat, loc, abl, gen, sense] of [
  ["kitap", "kitaby", "kitaba", "kitapda", "kitapdan", "kitabyň"], ["mekdep", "mekdebi", "mekdebe", "mekdepde", "mekdepden", "mekdebiň"],
  ["çörek", "çöregi", "çörege", "çörekde", "çörekden", "çöregiň"], ["agaç", "agajy", "agaja", "agaçda", "agaçdan", "agajyň"],
  ["talyp", "talyby", "talyba", "talypda", "talypdan", "talybyň"], ["kömek", "kömegi", "kömege", "kömekde", "kömekden", "kömegiň"],
  ["mowzuk", "mowzugy", "mowzuga", "mowzukda", "mowzukdan", "mowzugyň"], ["Aşgabat", "Aşgabady", "Aşgabada", "Aşgabatda", "Aşgabatdan", "Aşgabadyň"],
  ["döwlet", "döwleti", "döwlete", "döwletde", "döwletden", "döwletiň"], ["tarap", "tarapy", "tarapa", "tarapda", "tarapdan", "tarapyň"],
  ["at", "ady", "ada", "atda", "atdan", "adyň", 1], ["at", "aty", "ata", "atda", "atdan", "atyň", 2],
  ["ot", "ody", "oda", "otda", "otdan", "oduň", 1], ["ot", "oty", "ota", "otda", "otdan", "otuň", 2],
  ["saç", "saçy", "saça", "saçda", "saçdan", "saçyň"], ["öý", "öýi", "öýe", "öýde", "öýden", "öýüň"], ["göz", "gözi", "göze", "gözde", "gözden", "gözüň"],
  ["gün", "güni", "güne", "günde", "günden", "günüň"], ["suw", "suwy", "suwa", "suwda", "suwdan", "suwuň"], ["iş", "işi", "işe", "işde", "işden", "işiň"],
  ["ýol", "ýoly", "ýola", "ýolda", "ýoldan", "ýoluň"], ["dost", "dosty", "dosta", "dostda", "dostdan", "dostuň"],
  ["ýurt", "ýurdy", "ýurda", "ýurtda", "ýurtdan", "ýurduň"], ["ogul", "ogly", "ogla", "ogulda", "oguldan", "ogluň"],
  ["burun", "burny", "burna", "burunda", "burundan", "burnuň"], ["agyz", "agzy", "agza", "agyzda", "agyzdan", "agzyň"],
  ["Aýna", "Aýnany", "Aýna", "Aýnada", "Aýnadan", "Aýnanyň"], ["Mary", "Maryny", "Mara", "Maryda", "Marydan", "Marynyň"],
  ["okuwçy", "okuwçyny", "okuwça", "okuwçyda", "okuwçydan", "okuwçynyň"], ["kişi", "kişini", "kişä", "kişide", "kişiden", "kişiniň"],
  ["oba", "obany", "oba", "obada", "obadan", "obanyň"], ["eje", "ejäni", "ejä", "ejede", "ejeden", "ejäniň"],
  ["gije", "gijäni", "gijä", "gijede", "gijeden", "gijäniň"], ["hepde", "hepdäni", "hepdä", "hepdede", "hepdeden", "hepdäniň"],
  ["näme", "nämäni", "nämä", "nämede", "nämeden", "nämäniň"], ["kim", "kimi", "kime", "kimde", "kimden", "kimiň"],
  ["Merdan", "Merdany", "Merdana", "Merdanda", "Merdandan", "Merdanyň"], ["Türkmenistan", "Türkmenistany", "Türkmenistana", "Türkmenistanda", "Türkmenistandan", "Türkmenistanyň"],
  ["mugallym", "mugallymy", "mugallyma", "mugallymda", "mugallymdan", "mugallymyň"], ["otag", "otagy", "otaga", "otagda", "otagdan", "otagyň"],
  ["şäher", "şäheri", "şähere", "şäherde", "şäherden", "şäheriň"], ["stol", "stoly", "stola", "stolda", "stoldan", "stoluň"]]) {
  const o = sense ? { sense } : {}, label = sense ? `${w} (sense ${sense})` : w;
  check(`cases of ${label}`, () => ["acc", "dat", "loc", "abl", "gen"].map(c => dec(w, { ...o, case: c })), [acc, dat, loc, abl, gen]);
}
check("nirä, nirede, nireden", () => ["dat", "loc", "abl"].map(c => dec("nire", { case: c })), ["nirä", "nirede", "nireden"]);
check("homographs by gloss: at name, at horse", () => [dec("at", { sense: "name", poss: "men" }), dec("at", { sense: "horse", poss: "men" })], ["adym", "atym"]);
check("readings of at", () => M.readings("at").map(r => r.gloss), ["name", "horse"], "check");
check("the long-vowel list voices ýat, dört, gök: ýadyma, dördünji, gögi", () => [dec("ýat", { poss: "men", case: "dat" }), build("dört", ["NJY"]), dec("gök", { case: "acc" })],
  ["ýadyma", "dördünji", "gögi"]);
check("suffixes keep d after a voiceless consonant: mekdepde, işden, Aşgabatda, kitapdan", () =>
  [dec("mekdep", { case: "loc" }), dec("iş", { case: "abl" }), dec("Aşgabat", { case: "loc" }), dec("kitap", { case: "abl" })], ["mekdepde", "işden", "Aşgabatda", "kitapdan"]);
check("no apostrophe on names: Aşgabatda, Merdanyň", () => [dec("Aşgabat", { case: "loc" }), dec("Merdan", { case: "gen" })], ["Aşgabatda", "Merdanyň"]);

// ─────────────────────────── 3. possessives and the pronominal n ───────────────────────────
para("possessive", "kitap", "kitabym|kitabyň|kitaby|kitabymyz|kitabyňyz|kitaby");
para("possessive", "kitap", "-|-|-|-|-|kitaplary", true);
para("possessive", "çörek", "çöregim|çöregiň|çöregi|çöregimiz|çöregiňiz|çöregi");
para("possessive", "kaka", "kakam|kakaň|kakasy|kakamyz|kakaňyz|kakasy");
para("possessive", "eje", "ejäm|ejäň|ejesi|ejämiz|ejäňiz|ejesi");
para("possessive", "eje", "ejem|ejeň|-|ejemiz|ejeňiz|-", true);
para("possessive", "gije", "-|-|-|-|gijäňiz|-");
para("possessive", "gapy", "gapym|gapyň|gapysy|gapymyz|gapyňyz|gapysy");
para("possessive", "maşyn", "maşynym|maşynyň|maşyny|maşynymyz|maşynyňyz|maşyny");
para("possessive", "ogul", "oglum|ogluň|ogly|oglumyz|ogluňyz|ogly");
para("possessive", "burun", "burnum|burnuň|burny|burnumyz|burnuňyz|burny");
para("possessive", "agyz", "agzym|agzyň|agzy|agzymyz|agzyňyz|agzy");
para("possessive", "göwün", "göwnüm|göwnüň|göwni|göwnümiz|göwnüňiz|göwni");
para("possessive", "garyn", "garnym|-|garny|-|-|-");
para("possessive", "at", "adym|adyň|ady|adymyz|adyňyz|ady");
para("possessive", "at", "atym|atyň|aty|atymyz|atyňyz|aty", false, { sense: 2 });
para("possessive", "ýat", "-|-|ýady|-|-|-");
para("possessive-locative", "öý", "öýümde|öýüňde|öýünde|öýümizde|öýüňizde|öýünde");
para("possessive-dative", "öý", "öýüme|öýüňe|öýüne|öýümize|öýüňize|öýüne");
para("possessive-dative", "kitap", "kitabyma|kitabyňa|kitabyna|kitabymyza|kitabyňyza|kitabyna");
para("possessive-accusative", "kitap", "kitabymy|kitabyňy|kitabyny|kitabymyzy|kitabyňyzy|kitabyny");
para("possessive-bar", "dogan", "doganym bar|doganyň bar|dogany bar|doganymyz bar|doganyňyz bar|dogany bar");
para("possessive-yok", "maşyn", "maşynym ýok|maşynyň ýok|maşyny ýok|maşynymyz ýok|maşynyňyz ýok|maşyny ýok");
check("after a third-person possessive: öýüne, öýünde, öýünden, öýüni, öýüniň", () =>
  ["dat", "loc", "abl", "acc", "gen"].map(c => dec("öý", { poss: "ol", case: c })), ["öýüne", "öýünde", "öýünden", "öýüni", "öýüniň"]);
check("kitabyna, kitabynda, kitabyny, kitabynyň", () => ["dat", "loc", "acc", "gen"].map(c => dec("kitap", { poss: "ol", case: c })),
  ["kitabyna", "kitabynda", "kitabyny", "kitabynyň"]);
check("gapysyna, gapysynda, gapysyny, ejesinde", () => [dec("gapy", { poss: "ol", case: "dat" }), dec("gapy", { poss: "ol", case: "loc" }),
  dec("gapy", { poss: "ol", case: "acc" }), dec("eje", { poss: "ol", case: "loc" })], ["gapysyna", "gapysynda", "gapysyny", "ejesinde"]);
check("ogluna, oglunda, ogluny", () => ["dat", "loc", "acc"].map(c => dec("ogul", { poss: "ol", case: c })), ["ogluna", "oglunda", "ogluny"]);
check("kitaplarym, kitaplarymyz, öýlerimizde", () => [dec("kitap", { pl: true, poss: "men" }), dec("kitap", { pl: true, poss: "biz" }),
  dec("öý", { pl: true, poss: "biz", case: "loc" })], ["kitaplarym", "kitaplarymyz", "öýlerimizde"]);

// ─────────────────────────── 4. pronouns, plural, -kY, numbers, word building ───────────────────────────
para("pronoun-accusative", "men", "meni|seni|ony|bizi|sizi|olary");
para("pronoun-dative", "men", "maňa|saňa|oňa|bize|size|olara");
para("pronoun-locative", "men", "mende|sende|onda|bizde|sizde|olarda");
para("pronoun-ablative", "men", "menden|senden|ondan|bizden|sizden|olardan");
para("pronoun-genitive", "men", "meniň|seniň|onuň|biziň|siziň|olaryň");
para("pronoun-genitive-ky", "men", "meniňki|seniňki|onuňky|biziňki|siziňki|olaryňky");
for (const [w, acc, dat, loc, abl, gen] of [["bu", "muny", "muňa", "munda", "mundan", "munuň"], ["şu", "şuny", "şuňa", "şunda", "şundan", "şunuň"],
  ["şol", "şony", "şoňa", "şonda", "şondan", "şonuň"], ["ol", "ony", "oňa", "onda", "ondan", "onuň"]]) {
  check(`cases of ${w}`, () => ["acc", "dat", "loc", "abl", "gen"].map(c => dec(w, { case: c })), [acc, dat, loc, abl, gen]);
}
check("bular, şular, olar, şolar", () => ["bu", "şu", "ol", "şol"].map(w => dec(w, { pl: true })), ["bular", "şular", "olar", "şolar"]);
check("plural: kitaplar, öýler, ejeler, okuwçylar, gözler, talyplar, mugallymlar", () =>
  ["kitap", "öý", "eje", "okuwçy", "göz", "talyp", "mugallym"].map(w => dec(w, { pl: true })),
  ["kitaplar", "öýler", "ejeler", "okuwçylar", "gözler", "talyplar", "mugallymlar"]);
check("-dAky: öýdäki, Aşgabatdaky, mekdepdäki, otagdaky, öýdäkiler", () =>
  [build("öý", ["LOC", "KY"]), build("Aşgabat", ["LOC", "KY"]), build("mekdep", ["LOC", "KY"]), build("otag", ["LOC", "KY"]), build("öý", ["LOC", "KY", "PL"])],
  ["öýdäki", "Aşgabatdaky", "mekdepdäki", "otagdaky", "öýdäkiler"]);
check("-kY on time words: düýnki, şu günki, ertirki, agşamky, häzirki", () =>
  ["düýn", "şu gün", "ertir", "agşam", "häzir"].map(w => build(w, ["KY"])), ["düýnki", "şu günki", "ertirki", "agşamky", "häzirki"]);
check("Aýnanyňky, mugallymyňky", () => [build("Aýna", ["GEN", "KY"]), build("mugallym", ["GEN", "KY"])], ["Aýnanyňky", "mugallymyňky"]);
check("ordinals", () => ["bir", "iki", "üç", "dört", "bäş", "alty", "ýedi", "sekiz", "dokuz", "on", "ýigrimi", "otuz", "ýüz", "müň"].map(w => build(w, ["NJY"])),
  ["birinji", "ikinji", "üçünji", "dördünji", "bäşinji", "altynjy", "ýedinji", "sekizinji", "dokuzynjy", "onunjy", "ýigriminji", "otuzynjy", "ýüzünji", "müňünji"]);
for (const [w, ids, want] of [["şeker", ["LY"], "şekerli"], ["bulut", ["LY"], "bulutly"], ["Aşgabat", ["LY"], "Aşgabatly"], ["şeker", ["SYZ"], "şekersiz"],
  ["iş", ["SYZ"], "işsiz"], ["suw", ["SYZ"], "suwsuz"], ["okuw", ["CY"], "okuwçy"], ["balyk", ["CY"], "balykçy"], ["haly", ["CY"], "halyçy"],
  ["dost", ["LYK"], "dostluk"], ["gözel", ["LYK"], "gözellik"], ["garaşsyz", ["LYK"], "garaşsyzlyk"], ["dost", ["LYK", "ACC"], "dostlugy"],
  ["türkmen", ["CA"], "türkmençe"], ["iňlis", ["CA"], "iňlisçe"], ["rus", ["CA"], "rusça"], ["uly", ["RAK"], "ulurak"], ["kiçi", ["RAK"], "kiçiräk"],
  ["gowy", ["RAK"], "gowurak"], ["ýakyn", ["RAK"], "ýakynrak"], ["uzyn", ["RAK"], "uzynrak"]]) {
  check(`${w} + ${ids.join(" + ")}`, () => build(w, ids), want);
}

// ─────────────────────────── 5. "to be" ───────────────────────────
para("copula-present", "talyp", "talybyn|talypsyň|talyp|talybys|talypsyňyz|talyplar");
para("copula-present", "talyp", "talyp|talyp|talypdyr|talyp|talyp|talyp", true);
para("copula-present", "talyp", "-|-|-|-|-|talypdyrlar", true);
para("copula-present", "mugallym", "mugallymyn|mugallymsyň|mugallym|mugallymys|mugallymsyňyz|mugallymlar");
para("copula-present", "türkmen", "türkmenin|türkmensiň|türkmen|türkmenis|türkmensiňiz|türkmenler");
para("copula-present", "öýde", "öýde|öýdesiň|öýde|öýde|öýdesiňiz|öýdeler");
para("copula-present", "öýde", "-|-|öýdedir|-|-|-", true);
para("copula-present-negative", "talyp", "talyp dälin|talyp dälsiň|talyp däl|talyp dälis|talyp dälsiňiz|talyp däller");
para("copula-present-negative", "talyp", "talyp däl|talyp däl|talyp däldir|talyp däl|talyp däl|talyp däl", true);
para("copula-present-question", "talyp", "talybynmy|talypsyňmy|talypmy|talybysmy|talypsyňyzmy|talyplarmy");
para("copula-present-question", "talyp", "talypmy|talypmy|-|talypmy|talypmy|talypmy", true);
para("copula-present-question", "gowy", "-|-|gowumy|-|-|-");
para("copula-present-negative-question", "talyp", "talyp dälinmi|talyp dälsiňmi|talyp dälmi|talyp dälismi|talyp dälsiňizmi|talyp dällermi");
para("copula-present-negative-question", "talyp", "-|talyp dälmi|-|-|-|-", true);
para("copula-dyr", "talyp", "-|-|talypdyr|-|-|talypdyrlar");
para("copula-dyr", "öýde", "-|-|öýdedir|-|-|öýdedirler");
para("past-copula", "talyp", "talypdym|talypdyň|talypdy|talypdyk|talypdyňyz|talypdylar");
para("past-copula", "öýde", "öýdedim|öýdediň|öýdedi|öýdedik|öýdediňiz|öýdediler");
para("past-copula", "mugallym", "mugallymdym|-|mugallymdy|-|-|-");
para("past-copula-negative", "talyp", "talyp däldim|talyp däldiň|talyp däldi|talyp däldik|talyp däldiňiz|talyp däldiler");
para("past-copula-question", "talyp", "talypmydym|talypmydyň|talypmydy|talypmydyk|talypmydyňyz|talypmydylar");
check("bar and ýok: bardy, ýokdy, barmy, ýokmy, barmydy; the negative of bar is ýok", () => [
  M.copula("bar", { tense: "past", p: "ol" }).text, M.copula("ýok", { tense: "past", p: "ol" }).text, M.copula("bar", { q: true, p: "ol" }).text,
  M.copula("ýok", { q: true, p: "ol" }).text, M.copula("bar", { tense: "past", q: true, p: "ol" }).text, M.copula("bar", { neg: true, p: "ol" }).text,
  M.copula("bar", { tense: "past", neg: true, p: "ol" }).text], ["bardy", "ýokdy", "barmy", "ýokmy", "barmydy", "ýok", "ýokdy"]);
