check("analyze öý+üm+iz: a tile cuts a morpheme", () => { const r = an("öý", ["öý", "üm", "iz"]); return [r.reason, r.seg]; }, ["boundaries", "öý|ümiz"], "check");
check("seg: gel|ýär|in, öý|ü|n|e, Mar|a, işlä|p, o|n|y, ma|ň|a", () => [M.form("present", "gelmek", "men").seg, M.decline("öý", { poss: "ol", case: "dat" }).seg,
  M.decline("Mary", { case: "dat" }).seg, M.converb("işlemek").seg, M.decline("ol", { case: "acc" }).seg, M.decline("men", { case: "dat" }).seg],
  ["gel|ýär|in", "öý|ü|n|e", "Mar|a", "işlä|p", "o|n|y", "ma|ň|a"], "check");
check("forms() lists every slug with its negative and question", () =>
  ["copula-present", "present", "past", "future", "aorist", "necessitative", "ability", "past-copula", "optative", "imperative-3rd"].every(s =>
    M.formInfo(s) && M.formInfo(s + "-negative") && M.formInfo(s + "-question")), true, "check");
check("aliases: present-yar is present, maly is necessitative", () => [M.formInfo("present-yar").same, M.formInfo("maly").same], ["present", "necessitative"], "check");
check("no question of the 2nd-person imperative, no negative of the progressive", () => [M.formInfo("imperative-question"), M.formInfo("progressive-otyr-negative")], [null, null], "check");
check("persons a slug doesn't have give null", () => [M.form("imperative", "gelmek", "men"), M.form("optative", "gelmek", "ol"), M.form("perfect-ypdyr", "gelmek", "men")], [null, null, null], "check");

// ─────────────────────────── report ───────────────────────────
for (const f of failures) console.log(`FAIL ${f}`);
const total = failures.length;
console.log(`\nturkmen-morph.js · ${forms} known-correct forms and ${other} other checks: ${failures.length ? `${total} failed` : "all passed"}.`);
process.exit(failures.length ? 1 : 0);
